import{V as e,et as t,mt as n}from"./chunks/framework.BkS4K3kz.js";var r=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"rust-toolchain","text":"Install Rust and cache cargo in one action","tagline":"Reads the rust-toolchain.toml you already committed, installs it with rustup, and restores and saves the cargo cache in layers — no second action required.","actions":[{"theme":"brand","text":"Architecture","link":"/ARCHITECTURE"},{"theme":"alt","text":"What this replaces","link":"/COMPARISON"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/elioseverojunior/rust-toolchain"}]},"features":[{"title":"rust-toolchain.toml by default","details":"The channel, targets, components and profile come from the file already in your repository. Action inputs override it — scalars are replaced, lists merge deduped with your inputs leading."},{"title":"Layered cargo cache","details":"The registry and target directories are keyed separately, so a compiler bump no longer re-downloads the crates it never touched. The build key folds in the resolved toolchain and the CARGO_/RUST* environment."},{"title":"Saves what is worth saving","details":"An exact hit is never re-saved, a layer over cache-budget is skipped with a warning, and every layer's real outcome is reported in the job summary rather than behind one cache-hit boolean."},{"title":"RUSTUP_TOOLCHAIN wins later steps","details":"rustup default alone loses to a workspace rust-toolchain.toml. The resolved channel is exported so it applies to every later step, with set-rustup-toolchain false for monorepos that pin per crate."},{"title":"Typed outputs with provenance","details":"Every resolved value is published, lists as JSON arrays, plus a json output carrying all of them natively typed alongside inputs and toml blocks saying where each value came from."},{"title":"A drop-in superset","details":"The cachekey output matches dtolnay/rust-toolchain byte for byte, and cache-workspaces takes the same syntax as Swatinem/rust-cache, so an existing value transfers unchanged."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785598471000}`),i={name:`index.md`};function a(e,r,i,a,o,s){return n(),t(`div`)}var o=e(i,[[`render`,a]]);export{r as __pageData,o as default};